// The Nail Bawse "Build Your AI Agent" class page for thenailbawse.com (served by the thenailbawse-official Worker).
// Built by build.py from funnel-site/public. Routes: /webinar, /webinar/thanks, /registration (redirect),
// /webinar-assets/*, /api/events, /api/register, /api/ics. Sign-ups go to the same D1 "signups" table.
const ASSETS = {"index":{"t":"text/html; charset=utf-8","b":"<!doctype html>\n<html lang=\"en\" data-thanks=\"/webinar/thanks\">\n<head>\n<link rel=\"canonical\" href=\"https://thenailbawse.com/webinar\">\n<meta property=\"og:url\" content=\"https://thenailbawse.com/webinar\">\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Build Your AI Agent | Free Live Class with The Nail Bawse</title>\n<meta name=\"description\" content=\"A free live class for beauty professionals: build an AI agent that answers your DMs with your real prices and policies, and never sends without your OK.\">\n<meta property=\"og:title\" content=\"Build Your AI Agent: free live class with Anisia the Nail Bawse\">\n<meta property=\"og:description\" content=\"Build an AI agent that answers your client DMs with your real prices and policies. Free, live on Zoom.\">\n<meta name=\"theme-color\" content=\"#3B2621\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,600;1,9..144,400;1,9..144,600&family=Inter:wght@400;500;600;700;800&family=Caveat:wght@500;700&display=swap\">\n<link rel=\"stylesheet\" href=\"/webinar-assets/funnel.css\">\n</head>\n<body>\n\n<!-- Sticky: ticker + flip countdown -->\n<div class=\"topbar\" id=\"topbar\">\n  <div class=\"ticker\" aria-hidden=\"true\"><div class=\"ticker-track\" id=\"ticker\"><span>Free live class · Build Your AI Agent ·</span></div></div>\n  <div class=\"clockbar\" id=\"clockbar\" hidden>\n    <div class=\"flip\" id=\"flip1\" aria-label=\"Time until class\"></div>\n    <span class=\"livedot\">Live</span>\n  </div>\n</div>\n\n<main>\n<!-- HERO -->\n<section class=\"hero\">\n  <svg class=\"prop prop-polish\" viewBox=\"0 0 80 150\" aria-hidden=\"true\"><use href=\"#i-polish\"/></svg>\n  <svg class=\"prop prop-file\" viewBox=\"0 0 40 220\" aria-hidden=\"true\"><use href=\"#i-file\"/></svg>\n  <svg class=\"prop prop-nail\" viewBox=\"0 0 60 90\" aria-hidden=\"true\"><use href=\"#i-nail\"/></svg>\n  <svg class=\"prop prop-spark s1\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#i-spark\"/></svg>\n  <svg class=\"prop prop-spark s2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#i-spark\"/></svg>\n\n  <div class=\"brand\"><span class=\"mono\">NB</span><span>The Nail Bawse<small>Anisia Burroughs</small></span></div>\n  <p class=\"script\">free live class for beauty pros</p>\n  <h1 class=\"display\"><span id=\"title\">Build Your AI Agent</span><em>for your beauty business.</em></h1>\n  <svg class=\"swoosh\" viewBox=\"0 0 300 16\" aria-hidden=\"true\"><path d=\"M3 11 C 80 3, 190 2, 297 8\" /><path d=\"M40 14 C 120 8, 210 8, 270 12\" /></svg>\n  <p class=\"lead\" id=\"sub\">Build an AI agent that answers client DMs with your real prices, policies and voice, and never sends a word without your OK.</p>\n\n  <div class=\"datewrap\" id=\"session\" hidden>\n    <div class=\"picker\" id=\"picker\" aria-label=\"Choose a date\"></div>\n    <div class=\"apptbook\">\n      <div class=\"rings\" aria-hidden=\"true\"><i></i><i></i></div>\n      <div class=\"ab-month\" id=\"calMonth\"></div>\n      <div class=\"ab-day\" id=\"calDay\"></div>\n      <div class=\"ab-line\"><span>When</span><b id=\"calWeekday\"></b></div>\n      <div class=\"ab-line\"><span>Time</span><b id=\"calTime\"></b></div>\n    </div>\n    <svg class=\"seal\" viewBox=\"0 0 120 120\" aria-hidden=\"true\">\n      <defs><path id=\"sealPath\" d=\"M60,60 m-44,0 a44,44 0 1,1 88,0 a44,44 0 1,1 -88,0\"/></defs>\n      <circle cx=\"60\" cy=\"60\" r=\"58\" class=\"seal-bg\"/><circle cx=\"60\" cy=\"60\" r=\"31\" class=\"seal-in\"/>\n      <g class=\"seal-spin\"><text><textPath href=\"#sealPath\">LIVE ON ZOOM · FREE CLASS ·</textPath></text></g>\n      <text x=\"60\" y=\"66\" text-anchor=\"middle\" class=\"seal-mid\">LIVE</text>\n    </svg>\n  </div>\n  <p class=\"when-line\" id=\"whenline\" hidden><span id=\"when\"></span><span id=\"localwhen\"></span></p>\n\n  <section id=\"waitlist\" hidden class=\"soon\">\n    <p class=\"script\">next date drops soon</p>\n    <p>Leave your name and email and you'll get the date and your link to save a seat the moment it's posted.</p>\n  </section>\n\n  <form id=\"reg\" method=\"post\" action=\"/api/register\" novalidate>\n    <div class=\"form-head\"><span class=\"label\">Reserve your chair</span><span class=\"free\">Free</span></div>\n    <h2 id=\"formtitle\" class=\"caps\">Save my seat</h2>\n    <input type=\"hidden\" name=\"eventId\" id=\"eventId\" value=\"waitlist\">\n    <input type=\"hidden\" name=\"tz\" id=\"tz\"><input type=\"hidden\" name=\"ref\" id=\"ref\">\n    <div class=\"hp\" aria-hidden=\"true\"><label>Company<input name=\"company\" id=\"company\" tabindex=\"-1\" autocomplete=\"off\"></label></div>\n    <label class=\"field\"><span>First name</span><input name=\"firstName\" id=\"firstName\" autocomplete=\"given-name\" required placeholder=\"Your first name\"><span class=\"err\" data-for=\"firstName\"></span></label>\n    <label class=\"field\"><span>Email</span><input name=\"email\" id=\"email\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" required placeholder=\"you@email.com\"><span class=\"err\" data-for=\"email\"></span></label>\n    <label class=\"check\"><input type=\"checkbox\" name=\"optIn\" id=\"optIn\" checked><span>Email me when new free classes are posted. Unsubscribe anytime.</span></label>\n    <span class=\"err\" data-for=\"form\" role=\"alert\"></span>\n    <button class=\"cta\" type=\"submit\" id=\"submit\"><span id=\"submitText\">Save my seat</span><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg></button>\n    <p class=\"fine\">Zoom link by email right away, plus a reminder the day before and an hour before.</p>\n  </form>\n  <noscript><p class=\"soon\">Please turn on JavaScript to choose a date.</p></noscript>\n</section>\n\n<!-- DM DEMO -->\n<section class=\"sec dms\">\n  <p class=\"script\">sound familiar?</p>\n  <h2 class=\"display\">The DMs you answer <em>every single day.</em></h2>\n  <p class=\"lead\">In class you'll build an agent that drafts replies like this one, using <b>your</b> menu and <b>your</b> policies. You tap approve. That's it.</p>\n  <div class=\"phone\" id=\"dmPhone\">\n    <div class=\"phone-top\"><span class=\"notch\"></span></div>\n    <div class=\"chat-head\"><span class=\"avatar\">K</span><div><b>kiki.books.nails</b><small>Example client</small></div></div>\n    <div class=\"chat\" id=\"chat\">\n      <div class=\"msg in\" data-step=\"0\">hiii how much for a full set? 😩</div>\n      <div class=\"msg in\" data-step=\"1\">and do u have anything saturday??</div>\n      <div class=\"typing\" data-step=\"2\"><i></i><i></i><i></i><span>Your agent is drafting…</span></div>\n      <div class=\"msg out\" data-step=\"3\">Hi love! 💕 A full set starts at $65 and takes about 90 minutes. Saturday I have 11 AM or 2 PM open. Want me to hold one? A $20 deposit locks it in.\n        <span class=\"srcs\"><i>✓ price list</i><i>✓ booking calendar</i><i>✓ deposit policy</i></span></div>\n      <div class=\"approve\" data-step=\"4\"><span class=\"chip\">Draft · waiting for your OK</span><button type=\"button\" id=\"approveBtn\">Approve &amp; send</button></div>\n    </div>\n  </div>\n  <p class=\"note\">Example conversation. Prices and times come from your own business info.</p>\n</section>\n\n<!-- CLASS MENU -->\n<section class=\"sec menu-sec\">\n  <p class=\"script\">what you'll learn</p>\n  <h2 class=\"display\">The class <em>menu.</em></h2>\n  <div class=\"menu-card\">\n    <div class=\"menu-head\"><span class=\"mono sm\">NB</span><div><b>Service menu</b><small>Build Your AI Agent · live class</small></div></div>\n    <ol class=\"menu\">\n      <li><span class=\"m-n\">01</span><span class=\"m-t\"><b>Pick the one job</b><small>The DM you're tired of answering becomes your agent's first job.</small></span><span class=\"m-dots\"></span><span class=\"m-p\">incl.</span></li>\n      <li><span class=\"m-n\">02</span><span class=\"m-t\"><b>Give it your real info</b><small>Prices, policies, hours and your voice, so it never makes things up.</small></span><span class=\"m-dots\"></span><span class=\"m-p\">incl.</span></li>\n      <li><span class=\"m-n\">03</span><span class=\"m-t\"><b>Build it live, with me</b><small>Step by step on Zoom. No coding. Bring your phone.</small></span><span class=\"m-dots\"></span><span class=\"m-p\">incl.</span></li>\n      <li><span class=\"m-n\">04</span><span class=\"m-t\"><b>Check before it sends</b><small>A simple checklist so nothing wrong ever reaches a client.</small></span><span class=\"m-dots\"></span><span class=\"m-p\">incl.</span></li>\n    </ol>\n    <div class=\"menu-total\"><span>Total</span><span class=\"m-dots\"></span><b>FREE</b></div>\n    <p class=\"menu-foot\" id=\"menuFoot\">45 min · live on Zoom · bring your phone</p>\n  </div>\n  <p class=\"desc\" id=\"desc\"></p>\n</section>\n\n<!-- HOW IT WORKS -->\n<section class=\"sec dark how\">\n  <p class=\"script light\">your new front desk</p>\n  <h2 class=\"display light\">What your agent <em>does all day.</em></h2>\n  <div class=\"flow\">\n    <article class=\"win\"><header><i></i><i></i><i></i><span>Step / 01</span></header>\n      <div class=\"win-body\"><span class=\"big\">01</span><span class=\"ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 5h16v14H4zM8 9h8M8 13h5\"/></svg></span>\n      <h3>Learns your business</h3><p>Your menu, prices, deposit rules and how you talk to clients.</p>\n      <div class=\"status\"><span class=\"pulse\"></span>Loading your price list<b class=\"bar\"><i style=\"--w:72%\"></i></b></div></div></article>\n    <article class=\"win\"><header><i></i><i></i><i></i><span>Step / 02</span></header>\n      <div class=\"win-body\"><span class=\"big\">02</span><span class=\"ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16v10H9l-5 4z\"/></svg></span>\n      <h3>Reads the DM</h3><p>Figures out what the client actually wants: price, booking, aftercare.</p>\n      <div class=\"status\"><span class=\"pulse\"></span>Reading new message<b class=\"bar\"><i style=\"--w:48%\"></i></b></div></div></article>\n    <article class=\"win\"><header><i></i><i></i><i></i><span>Step / 03</span></header>\n      <div class=\"win-body\"><span class=\"big\">03</span><span class=\"ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 20l4-1 11-11-3-3L5 16zM14 6l3 3\"/></svg></span>\n      <h3>Drafts your reply</h3><p>In your voice, with your real numbers. No guessing.</p>\n      <div class=\"status\"><span class=\"pulse\"></span>Drafting in progress<b class=\"bar\"><i style=\"--w:86%\"></i></b></div></div></article>\n    <article class=\"win\"><header><i></i><i></i><i></i><span>Step / 04</span></header>\n      <div class=\"win-body\"><span class=\"big\">04</span><span class=\"ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 12l4 4L19 6\"/></svg></span>\n      <h3>Waits for your OK</h3><p>You approve, edit or skip. You stay in control.</p>\n      <div class=\"status\"><span class=\"pulse\"></span>Waiting for you<b class=\"bar\"><i style=\"--w:100%\"></i></b></div></div></article>\n  </div>\n  <p class=\"pull light\">You bring the skill. <em>Your agent handles the desk.</em></p>\n  <a class=\"cta light\" href=\"#reg\" data-cta><span>Save my seat</span><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg></a>\n</section>\n\n<!-- BEFORE / AFTER -->\n<section class=\"sec\">\n  <p class=\"script\">habit check</p>\n  <h2 class=\"display\">Before <em>vs.</em> after</h2>\n  <div class=\"ba\">\n    <div class=\"ba-row\"><div class=\"ba-b\"><small>Before</small><s>Answering DMs at 11 PM</s></div><div class=\"ba-a\"><small>With your agent</small>Replies drafted while you're with a client</div></div>\n    <div class=\"ba-row\"><div class=\"ba-b\"><small>Before</small><s>Typing your prices for the 100th time</s></div><div class=\"ba-a\"><small>With your agent</small>The same right answer, every time</div></div>\n    <div class=\"ba-row\"><div class=\"ba-b\"><small>Before</small><s>Booking requests lost in your inbox</s></div><div class=\"ba-a\"><small>With your agent</small>Every request gets a reply</div></div>\n    <div class=\"ba-row\"><div class=\"ba-b\"><small>Before</small><s>Scared AI will say something wrong</s></div><div class=\"ba-a\"><small>With your agent</small>Nothing sends without your OK</div></div>\n  </div>\n</section>\n\n<!-- FOR YOU IF -->\n<section class=\"sec notes-sec\">\n  <p class=\"script\">roll call</p>\n  <h2 class=\"display\">This is for you <em>if…</em></h2>\n  <p class=\"tapnote\">tap the ones that sound like you <svg viewBox=\"0 0 40 20\" aria-hidden=\"true\"><path d=\"M2 4 C 14 18, 26 16, 36 8 M30 6 l6 2 -3 6\"/></svg></p>\n  <div class=\"notes\" id=\"notes\">\n    <button type=\"button\" class=\"note-card\" aria-pressed=\"false\"><span class=\"box\"></span>You're booked, but everything still runs through you.</button>\n    <button type=\"button\" class=\"note-card\" aria-pressed=\"false\"><span class=\"box\"></span>You answer the same client questions over and over.</button>\n    <button type=\"button\" class=\"note-card\" aria-pressed=\"false\"><span class=\"box\"></span>You've tried ChatGPT, but nothing stuck.</button>\n    <button type=\"button\" class=\"note-card\" aria-pressed=\"false\"><span class=\"box\"></span>You lose bookings because you couldn't reply fast enough.</button>\n    <button type=\"button\" class=\"note-card\" aria-pressed=\"false\"><span class=\"box\"></span>You want something you can use Monday, not theory.</button>\n  </div>\n  <p class=\"tally\" id=\"tally\" aria-live=\"polite\"></p>\n</section>\n\n<!-- HOST -->\n<section class=\"sec host\">\n  <p class=\"script\">meet your teacher</p>\n  <div class=\"host-card\">\n    <figure class=\"polaroid\"><span class=\"tape\" aria-hidden=\"true\"></span><img src=\"/webinar-assets/anisia.jpg\" width=\"900\" height=\"900\" alt=\"Anisia Burroughs, founder of The Nail Bawse\" loading=\"lazy\"><figcaption>Anisia, your teacher</figcaption></figure>\n    <h2 class=\"display\">Anisia <em>Burroughs.</em></h2>\n    <p class=\"label\">Founder of The Nail Bawse · Los Angeles</p>\n    <p>Licensed cosmetologist and nail tech. After years behind the chair, I teach beauty pros to turn what they already know into AI systems that actually work, checked against their real business before anything goes live.</p>\n    <div class=\"chips\"><span>Licensed cosmetologist</span><span>Nail tech</span><span>Educator</span><span>AI systems</span></div>\n    <p class=\"sig\">You are the asset. Build accordingly.</p>\n  </div>\n</section>\n\n<!-- FINAL -->\n<section class=\"sec final\" id=\"final\" hidden>\n  <p class=\"script light\">your chair is waiting</p>\n  <h2 class=\"display light\">See you <em>live.</em></h2>\n  <p class=\"final-date\" id=\"finalWhen\"></p>\n  <div class=\"zones\" id=\"zones\"></div>\n  <div class=\"flip big\" id=\"flip2\" aria-hidden=\"true\"></div>\n  <a class=\"cta pink\" href=\"#reg\" data-cta><span>Save my seat</span><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg></a>\n  <p class=\"fine light\">Free to attend · live on Zoom</p>\n</section>\n\n<footer class=\"foot\">\n  <span class=\"mono\">NB</span>\n  <p>Beyond the service. Beyond the title.</p>\n  <p class=\"small\">© The Nail Bawse · <a href=\"https://www.instagram.com/thenailbawse/\" target=\"_blank\" rel=\"noopener\">@thenailbawse</a></p>\n</footer>\n</main>\n\n<a class=\"float-cta\" id=\"floatCta\" href=\"#reg\" data-cta hidden>Save my seat</a>\n\n<!-- Icon sprites (drawn for The Nail Bawse) -->\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <defs>\n    <linearGradient id=\"g-polish\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#F7BFD4\"/><stop offset=\".55\" stop-color=\"#F4A6C4\"/><stop offset=\"1\" stop-color=\"#D9799F\"/></linearGradient>\n    <linearGradient id=\"g-cap\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#5A3A31\"/><stop offset=\".5\" stop-color=\"#3B2621\"/><stop offset=\"1\" stop-color=\"#24150F\"/></linearGradient>\n    <linearGradient id=\"g-file\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#E9D6C4\"/><stop offset=\"1\" stop-color=\"#CDB39B\"/></linearGradient>\n    <symbol id=\"i-polish\" viewBox=\"0 0 80 150\">\n      <rect x=\"27\" y=\"4\" width=\"26\" height=\"58\" rx=\"5\" fill=\"url(#g-cap)\"/><rect x=\"31\" y=\"8\" width=\"4\" height=\"48\" rx=\"2\" fill=\"#fff\" opacity=\".18\"/>\n      <rect x=\"22\" y=\"58\" width=\"36\" height=\"10\" rx=\"3\" fill=\"#2A1A15\"/>\n      <path d=\"M14 76 Q14 66 26 66 H54 Q66 66 66 76 V132 Q66 146 52 146 H28 Q14 146 14 132 Z\" fill=\"url(#g-polish)\"/>\n      <path d=\"M21 78 Q21 72 28 72 H33 V138 H28 Q21 138 21 130 Z\" fill=\"#fff\" opacity=\".35\"/>\n      <rect x=\"25\" y=\"96\" width=\"30\" height=\"22\" rx=\"3\" fill=\"#FFF8F2\" opacity=\".85\"/><text x=\"40\" y=\"111\" text-anchor=\"middle\" font-family=\"Georgia,serif\" font-style=\"italic\" font-size=\"10\" fill=\"#3B2621\">NB</text>\n    </symbol>\n    <symbol id=\"i-file\" viewBox=\"0 0 40 220\">\n      <rect x=\"6\" y=\"4\" width=\"28\" height=\"212\" rx=\"14\" fill=\"url(#g-file)\"/>\n      <rect x=\"6\" y=\"110\" width=\"28\" height=\"106\" rx=\"14\" fill=\"#F4A6C4\"/><rect x=\"6\" y=\"110\" width=\"28\" height=\"12\" fill=\"#F4A6C4\"/>\n      <g fill=\"#8B6B57\" opacity=\".35\"><circle cx=\"14\" cy=\"30\" r=\"1\"/><circle cx=\"24\" cy=\"44\" r=\"1\"/><circle cx=\"18\" cy=\"60\" r=\"1\"/><circle cx=\"27\" cy=\"78\" r=\"1\"/><circle cx=\"13\" cy=\"92\" r=\"1\"/><circle cx=\"22\" cy=\"20\" r=\"1\"/></g>\n      <g fill=\"#fff\" opacity=\".35\"><circle cx=\"15\" cy=\"140\" r=\"1\"/><circle cx=\"25\" cy=\"160\" r=\"1\"/><circle cx=\"17\" cy=\"182\" r=\"1\"/><circle cx=\"26\" cy=\"198\" r=\"1\"/></g>\n    </symbol>\n    <symbol id=\"i-nail\" viewBox=\"0 0 60 90\">\n      <path d=\"M8 86 V40 C8 14 20 4 30 4 C40 4 52 14 52 40 V86 Z\" fill=\"#F4A6C4\" stroke=\"#3B2621\" stroke-width=\"2\"/>\n      <path d=\"M16 70 V42 C16 22 23 12 30 11\" fill=\"none\" stroke=\"#fff\" stroke-width=\"5\" stroke-linecap=\"round\" opacity=\".55\"/>\n    </symbol>\n    <symbol id=\"i-spark\" viewBox=\"0 0 24 24\"><path d=\"M12 0 C13 8 16 11 24 12 C16 13 13 16 12 24 C11 16 8 13 0 12 C8 11 11 8 12 0Z\"/></symbol>\n  </defs>\n</svg>\n<script src=\"/webinar-assets/app.js\"></script>\n</body>\n</html>\n"},"thanks":{"t":"text/html; charset=utf-8","b":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>You're booked | The Nail Bawse</title><meta name=\"robots\" content=\"noindex\"><meta name=\"theme-color\" content=\"#3B2621\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,600;1,9..144,400;1,9..144,600&family=Inter:wght@400;500;600;700;800&family=Caveat:wght@500;700&display=swap\">\n<link rel=\"stylesheet\" href=\"/webinar-assets/funnel.css\">\n</head>\n<body class=\"thanks\">\n<div class=\"topbar\"><div class=\"ticker\" aria-hidden=\"true\"><div class=\"ticker-track\" id=\"ticker\"></div></div></div>\n<main>\n<section class=\"hero ty-hero\">\n  <svg class=\"prop prop-polish\" viewBox=\"0 0 80 150\" aria-hidden=\"true\"><use href=\"#i-polish\"/></svg>\n  <svg class=\"prop prop-spark s1\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#i-spark\"/></svg>\n  <div class=\"brand\"><span class=\"mono\">NB</span><span>The Nail Bawse<small>Anisia Burroughs</small></span></div>\n  <h1 class=\"display\" id=\"h\">You're <em>booked.</em></h1>\n  <p class=\"lead\" id=\"msg\">Your seat is saved. Here's your appointment card. Download it, post it to your story, and tag me.</p>\n\n  <div class=\"appt\" id=\"appt\" hidden>\n    <div class=\"appt-top\"><span class=\"mono sm\">NB</span><div><b>The Nail Bawse</b><small>Appointment card</small></div><span class=\"appt-free\">Free</span></div>\n    <div class=\"appt-row\"><span>For</span><b id=\"aName\">You</b></div>\n    <div class=\"appt-row\"><span>Service</span><b id=\"aTitle\"></b></div>\n    <div class=\"appt-row\"><span>Date</span><b id=\"aDate\"></b></div>\n    <div class=\"appt-row\"><span>Time</span><b id=\"aTime\"></b></div>\n    <div class=\"appt-row\"><span>With</span><b>Anisia</b></div>\n    <div class=\"appt-foot\"><span>Live on Zoom</span><span>@thenailbawse</span></div>\n    <div class=\"stamp\" aria-hidden=\"true\">Confirmed</div>\n  </div>\n  <button class=\"cta\" type=\"button\" id=\"story\" hidden><span id=\"storyText\">Download my card</span><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 4v11M7 10l5 5 5-5M5 20h14\"/></svg></button>\n  <p class=\"fine\" id=\"saveHint\" hidden>Saves a story-size picture of your card. On iPhone, choose \"Save Image\".</p>\n  <p class=\"script center\" id=\"tagline\" hidden>post it &amp; tag @thenailbawse, I'm reposting!</p>\n</section>\n\n<section class=\"sec ty-steps\" id=\"steps\">\n  <p class=\"script\">before we go live</p>\n  <h2 class=\"display\">Three things <em>to do next.</em></h2>\n\n  <article class=\"step-card\">\n    <span class=\"step-n\">01</span>\n    <div><h3>Check your inbox</h3>\n    <p id=\"inbox\">Your Zoom link and calendar invite are on the way. Not there in a few minutes? Check Promotions or Spam and move it to your inbox so your reminders land.</p></div>\n  </article>\n\n  <article class=\"step-card\" id=\"calStep\" hidden>\n    <span class=\"step-n\">02</span>\n    <div><h3>Add it to your calendar</h3>\n    <p>So your Zoom link is right there when it's time.</p>\n    <div class=\"cal-btns\"><a class=\"pill\" id=\"gcal\" target=\"_blank\" rel=\"noopener\">Google Calendar</a><a class=\"pill\" id=\"ics\">Apple / iPhone</a><a class=\"pill\" id=\"ics2\">Outlook</a></div></div>\n  </article>\n\n  <article class=\"step-card\">\n    <span class=\"step-n\" id=\"n3\">03</span>\n    <div><h3>Pick the DM you're done answering</h3>\n    <p>We'll build your agent around it live. Tap one:</p>\n    <div class=\"pick\" id=\"pick\">\n      <button type=\"button\" aria-pressed=\"false\">\"How much is a…?\"</button>\n      <button type=\"button\" aria-pressed=\"false\">\"Do you have anything…?\"</button>\n      <button type=\"button\" aria-pressed=\"false\">Deposit &amp; late policy</button>\n      <button type=\"button\" aria-pressed=\"false\">Aftercare questions</button>\n    </div>\n    <p class=\"script small\" id=\"pickNote\" aria-live=\"polite\"></p></div>\n  </article>\n\n  <div class=\"signoff-row\"><img src=\"/webinar-assets/anisia-face.jpg\" width=\"160\" height=\"160\" alt=\"\"><p class=\"sig\">See you there,<br>Anisia</p></div>\n</section>\n<footer class=\"foot\"><span class=\"mono\">NB</span><p>You are the asset. Build accordingly.</p><p class=\"small\">© The Nail Bawse · <a href=\"https://www.instagram.com/thenailbawse/\" target=\"_blank\" rel=\"noopener\">@thenailbawse</a></p></footer>\n</main>\n\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <defs>\n    <linearGradient id=\"g-polish\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#F7BFD4\"/><stop offset=\".55\" stop-color=\"#F4A6C4\"/><stop offset=\"1\" stop-color=\"#D9799F\"/></linearGradient>\n    <linearGradient id=\"g-cap\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#5A3A31\"/><stop offset=\".5\" stop-color=\"#3B2621\"/><stop offset=\"1\" stop-color=\"#24150F\"/></linearGradient>\n    <symbol id=\"i-polish\" viewBox=\"0 0 80 150\">\n      <rect x=\"27\" y=\"4\" width=\"26\" height=\"58\" rx=\"5\" fill=\"url(#g-cap)\"/><rect x=\"31\" y=\"8\" width=\"4\" height=\"48\" rx=\"2\" fill=\"#fff\" opacity=\".18\"/>\n      <rect x=\"22\" y=\"58\" width=\"36\" height=\"10\" rx=\"3\" fill=\"#2A1A15\"/>\n      <path d=\"M14 76 Q14 66 26 66 H54 Q66 66 66 76 V132 Q66 146 52 146 H28 Q14 146 14 132 Z\" fill=\"url(#g-polish)\"/>\n      <path d=\"M21 78 Q21 72 28 72 H33 V138 H28 Q21 138 21 130 Z\" fill=\"#fff\" opacity=\".35\"/>\n      <rect x=\"25\" y=\"96\" width=\"30\" height=\"22\" rx=\"3\" fill=\"#FFF8F2\" opacity=\".85\"/><text x=\"40\" y=\"111\" text-anchor=\"middle\" font-family=\"Georgia,serif\" font-style=\"italic\" font-size=\"10\" fill=\"#3B2621\">NB</text>\n    </symbol>\n    <symbol id=\"i-spark\" viewBox=\"0 0 24 24\"><path d=\"M12 0 C13 8 16 11 24 12 C16 13 13 16 12 24 C11 16 8 13 0 12 C8 11 11 8 12 0Z\"/></symbol>\n  </defs>\n</svg>\n<script src=\"/webinar-assets/card.js\"></script>\n<script>\n(function () {\n  var $ = function (id) { return document.getElementById(id); };\n  var p = new URLSearchParams(location.search), id = p.get(\"e\"), name = (p.get(\"n\") || \"\").trim().slice(0, 30);\n  var tz = \"\"; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || \"\"; } catch (e) {}\n  function ticker(items) { var t = $(\"ticker\"); t.textContent = \"\"; for (var r = 0; r < 2; r++) { var s = document.createElement(\"span\"); for (var k = 0; k < 2; k++) items.forEach(function (x, i) { var b = document.createElement(i % 2 ? \"b\" : \"span\"); b.textContent = x + \" · \"; s.appendChild(b); }); t.appendChild(s); } }\n  ticker([\"You're booked\", \"Build Your AI Agent\", \"Add it to your calendar\", \"Tag @thenailbawse\"]);\n  if (p.get(\"m\") === \"0\") $(\"inbox\").textContent = \"Your confirmation email is running a little behind; it will reach you before class. Keep this page open or screenshot your card in the meantime.\";\n\n  // Step 3 picker\n  document.querySelectorAll(\"#pick button\").forEach(function (b) {\n    b.addEventListener(\"click\", function () {\n      document.querySelectorAll(\"#pick button\").forEach(function (x) { x.setAttribute(\"aria-pressed\", String(x === b)); });\n      $(\"pickNote\").textContent = \"Got it. Bring a real example of that DM to class.\";\n    });\n  });\n\n  if (!id || id === \"waitlist\") {\n    $(\"h\").innerHTML = \"You're on <em>the list.</em>\";\n    $(\"msg\").textContent = \"The moment the next date is posted, you'll get it by email with your link to save a seat.\";\n    $(\"steps\").hidden = true; return;\n  }\n\n  var ev = null;\n  fetch(\"/api/events?id=\" + encodeURIComponent(id)).then(function (r) { return r.json(); }).then(function (d) {\n    ev = d.event; if (!ev) return;\n    var zone = tz || ev.tz, start = new Date(ev.startUtc), end = new Date(start.getTime() + (ev.durationMin || 45) * 60000);\n    var f = function (o) { return new Intl.DateTimeFormat(\"en-US\", Object.assign({ timeZone: zone }, o)).format(start); };\n    if (name) $(\"aName\").textContent = name;\n    $(\"aTitle\").textContent = ev.title;\n    $(\"aDate\").textContent = f({ weekday: \"long\", month: \"long\", day: \"numeric\" });\n    $(\"aTime\").textContent = f({ hour: \"numeric\", minute: \"2-digit\", timeZoneName: \"short\" });\n    $(\"appt\").hidden = false; $(\"story\").hidden = false; $(\"saveHint\").hidden = false; $(\"tagline\").hidden = false;\n    ticker([\"You're booked\", ev.title, f({ weekday: \"short\", month: \"short\", day: \"numeric\" }), f({ hour: \"numeric\", minute: \"2-digit\", timeZoneName: \"short\" }), \"Tag @thenailbawse\"]);\n    var z = function (d) { return d.toISOString().replace(/[-:]/g, \"\").replace(/\\.\\d{3}/, \"\"); };\n    $(\"gcal\").href = \"https://calendar.google.com/calendar/render?\" + new URLSearchParams({ action: \"TEMPLATE\", text: ev.title, dates: z(start) + \"/\" + z(end), details: \"Your Zoom link is in your confirmation email.\", location: \"Online (Zoom)\" });\n    $(\"ics\").href = $(\"ics2\").href = \"/api/ics?id=\" + encodeURIComponent(ev.id);\n    $(\"calStep\").hidden = false;\n    if (ev.joinUrl) {\n      var st = $(\"inbox\").parentNode;\n      st.querySelector(\"h3\").textContent = \"Save your Zoom link\";\n      $(\"inbox\").textContent = \"This is your room for class. It's also in your calendar invite.\";\n      var a = document.createElement(\"a\"); a.className = \"pill\"; a.href = ev.joinUrl; a.target = \"_blank\"; a.rel = \"noopener\"; a.textContent = \"Open my Zoom link\";\n      var row = document.createElement(\"div\"); row.className = \"cal-btns\"; row.appendChild(a); st.appendChild(row);\n    }\n  }).catch(function () { $(\"n3\").textContent = \"02\"; });\n\n  // Download the appointment card: share sheet on phones (Save Image), file download elsewhere\n  $(\"story\").addEventListener(\"click\", function () {\n    if (!ev) return;\n    $(\"storyText\").textContent = \"Making your card…\";\n    window.NBCard.draw({ name: $(\"aName\").textContent, title: $(\"aTitle\").textContent, date: $(\"aDate\").textContent, time: $(\"aTime\").textContent }).then(function (c) {\n      c.toBlob(function (blob) {\n        var name = \"nail-bawse-appointment-card.png\";\n        $(\"storyText\").textContent = \"Download my card\";\n        if (window.NBSave) { window.NBSave(blob, name); return; }\n        var file = new File([blob], name, { type: \"image/png\" });\n        if (navigator.canShare && navigator.canShare({ files: [file] })) { navigator.share({ files: [file], title: \"My appointment card\" }).catch(function () {}); return; }\n        var a = document.createElement(\"a\"); a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click(); a.remove();\n        $(\"storyText\").textContent = \"Saved ✓\";\n      }, \"image/png\");\n    });\n  });\n})();\n</script>\n</body>\n</html>\n"},"funnel.css":{"t":"text/css; charset=utf-8","b":"/* The Nail Bawse: free class funnel. Espresso + cream + blush, editorial serif, bold caps labels, handwritten accents. */\n:root{\n  --espresso:#3B2621; --espresso-2:#2A1A15; --cream:#FBF6F1; --paper:#FFFDFB; --tan:#EFE4DA; --blush:#F8E1EA;\n  --pink:#F4A6C4; --pink-2:#F9C9DB; --rose:#A24D6E; --ink:#2A1A15; --muted:#76605A; --line:#E7D8CE; --ok:#2F7A55; --err:#B3261E;\n  --serif:\"Fraunces\",Georgia,\"Times New Roman\",serif; --sans:\"Inter\",system-ui,-apple-system,\"Segoe UI\",sans-serif; --hand:\"Caveat\",\"Segoe Print\",cursive;\n  --top:92px; color-scheme:light;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scroll-padding-top:calc(var(--top) + 12px)}\nhtml,body{margin:0}\nbody{background:var(--cream);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.55;overflow-x:clip;\n  background-image:radial-gradient(rgba(59,38,33,.07) 1px,transparent 1.2px);background-size:18px 18px}\nmain{overflow-x:clip}\nh1,h2,h3,p{margin:0}\na{color:var(--rose)}\n[hidden]{display:none!important}\n.caps{text-transform:uppercase;letter-spacing:.06em;font-weight:800}\n.label{font-size:.7rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}\n.script{font-family:var(--hand);font-size:1.6rem;line-height:1;color:var(--rose);font-weight:700}\n.script.light{color:var(--pink)}\n.display{font-family:var(--serif);font-weight:400;font-size:clamp(2.1rem,9vw,3.4rem);line-height:1.02;letter-spacing:-.02em;text-wrap:balance}\n.display em{font-style:italic;color:var(--rose);display:block}\n.display.light{color:var(--cream)} .display.light em{color:var(--pink)}\n.lead{font-size:1.04rem;color:var(--muted);max-width:34ch}\n.lead b{color:var(--ink)}\n.mono{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:9px;background:var(--espresso);color:var(--cream);font-family:var(--serif);font-style:italic;font-size:1rem;flex:none}\n.mono.sm{width:32px;height:32px;font-size:.85rem}\n\n/* ---------- Sticky top: ticker + flip clock ---------- */\n.topbar{position:sticky;top:0;z-index:30;box-shadow:0 6px 18px rgba(42,26,21,.12)}\n.ticker{background:var(--espresso);color:var(--cream);overflow:hidden;white-space:nowrap;font-size:.7rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase;height:30px;display:flex;align-items:center}\n.ticker-track{display:inline-flex;gap:0;animation:tick 28s linear infinite;will-change:transform}\n.ticker-track span{padding-right:.6em}\n.ticker-track span b{color:var(--pink);font-weight:800}\n@keyframes tick{to{transform:translateX(-50%)}}\n.clockbar{background:var(--pink);display:flex;align-items:center;justify-content:center;gap:12px;padding:7px 10px;position:relative}\n.livedot{position:absolute;right:10px;top:50%;transform:translateY(-50%);background:var(--espresso);color:var(--cream);font-size:.62rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;padding:4px 9px 4px 20px;border-radius:999px}\n.livedot::before{content:\"\";position:absolute;left:8px;top:50%;width:7px;height:7px;margin-top:-3.5px;border-radius:50%;background:#FF4D7E;animation:blink 1.4s infinite}\n@keyframes blink{50%{opacity:.25}}\n\n/* Flip digits */\n.flip{display:flex;align-items:flex-start;gap:5px}\n.flip .unit{display:flex;flex-direction:column;align-items:center;gap:2px}\n.flip .pair{display:flex;gap:2px}\n.flip .d{position:relative;width:19px;height:26px;border-radius:4px;background:linear-gradient(#4A302A 0 50%,#3B2621 50% 100%);color:var(--pink-2);\n  font-family:var(--sans);font-weight:800;font-size:1.05rem;display:grid;place-items:center;font-variant-numeric:tabular-nums;box-shadow:0 2px 0 rgba(0,0,0,.25);perspective:120px}\n.flip .d::after{content:\"\";position:absolute;left:0;right:0;top:50%;height:1px;background:rgba(0,0,0,.45)}\n.flip .d.flip-in{animation:flipin .45s cubic-bezier(.3,1.4,.6,1)}\n@keyframes flipin{0%{transform:rotateX(-80deg);filter:brightness(1.6)}100%{transform:none}}\n.flip .u{font-size:.52rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--espresso)}\n.flip .colon{font-weight:800;color:var(--espresso);padding-top:3px}\n.flip.big{justify-content:center;gap:8px}\n.flip.big .d{width:34px;height:48px;font-size:1.9rem;border-radius:7px;color:var(--pink)}\n.flip.big .u{color:var(--pink-2);font-size:.6rem}\n.flip.big .colon{color:var(--pink);padding-top:10px;font-size:1.3rem}\n\n/* ---------- Hero ---------- */\n.hero{position:relative;max-width:560px;margin:0 auto;padding:22px 16px 40px;display:flex;flex-direction:column;gap:16px}\n.brand{display:flex;align-items:center;gap:10px;font-weight:800;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase}\n.brand small{display:block;font-size:.6rem;color:var(--muted);letter-spacing:.18em;font-weight:600}\n.hero .script{margin-top:10px}\n.hero h1{font-size:clamp(2.6rem,12.5vw,4.4rem);position:relative;z-index:2}\n.hero h1 em{font-size:.62em;margin-top:.12em}\n.swoosh{width:min(78%,320px);height:16px;margin-top:-8px;fill:none;stroke:var(--pink);stroke-width:3;stroke-linecap:round}\n.swoosh path{stroke-dasharray:340;stroke-dashoffset:340;animation:draw 1.4s .4s ease-out forwards}\n.swoosh path+path{stroke-width:2;opacity:.7;animation-delay:.8s}\n@keyframes draw{to{stroke-dashoffset:0}}\n\n.prop{position:absolute;pointer-events:none;z-index:1;filter:drop-shadow(0 10px 12px rgba(42,26,21,.18))}\n.prop-polish{width:58px;right:-6px;top:96px;transform:rotate(14deg);animation:bob 6s ease-in-out infinite}\n.prop-file{width:20px;right:14px;top:470px;transform:rotate(-28deg);animation:bob 7s 1s ease-in-out infinite;opacity:.95}\n.prop-nail{width:28px;left:14px;top:560px;transform:rotate(-18deg);animation:bob 5.5s .5s ease-in-out infinite}\n.prop-spark{width:16px;fill:var(--pink);filter:none;animation:twinkle 2.6s ease-in-out infinite}\n.prop-spark.s1{right:78px;top:84px}.prop-spark.s2{left:40px;top:520px;width:11px;animation-delay:1.2s;fill:var(--rose)}\n@keyframes bob{50%{translate:0 -8px}}\n@keyframes twinkle{50%{transform:scale(.5) rotate(45deg);opacity:.5}}\n\n.datewrap{position:relative;display:flex;flex-direction:column;align-items:center;gap:12px;margin:12px 0 2px}\n.picker{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}\n.picker button{font:inherit;font-size:.82rem;font-weight:700;padding:7px 12px;border-radius:999px;border:1.5px solid var(--espresso);background:var(--paper);color:var(--ink);cursor:pointer}\n.picker button[aria-pressed=\"true\"]{background:var(--espresso);color:var(--cream)}\n.apptbook{position:relative;width:200px;background:var(--paper);border-radius:6px 6px 10px 10px;padding:30px 16px 14px;transform:rotate(-3deg);\n  box-shadow:0 1px 0 var(--line),0 18px 30px -12px rgba(42,26,21,.35);border-top:22px solid var(--pink);text-align:center}\n.apptbook::after{content:\"\";position:absolute;inset:auto 6px -7px 6px;height:12px;background:var(--tan);border-radius:0 0 8px 8px;z-index:-1}\n.rings{position:absolute;top:-34px;left:0;right:0;display:flex;justify-content:space-between;padding:0 18px}\n.rings i{width:14px;height:26px;border-radius:8px;border:4px solid var(--espresso);border-bottom-color:transparent;background:transparent}\n.ab-month{position:absolute;top:-22px;left:0;right:0;height:22px;line-height:22px;font-size:.72rem;font-weight:800;letter-spacing:.3em;text-transform:uppercase;color:var(--espresso)}\n.ab-day{font-family:var(--serif);font-size:4.4rem;line-height:.9;color:var(--espresso)}\n.ab-line{display:flex;justify-content:space-between;align-items:baseline;gap:8px;border-bottom:1.5px dashed var(--line);padding:7px 2px 3px;font-size:.62rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.ab-line b{font-family:var(--hand);font-size:1.25rem;letter-spacing:0;text-transform:none;color:var(--rose);font-weight:700}\n.seal{position:absolute;width:92px;right:calc(50% - 190px);bottom:-30px;filter:drop-shadow(0 6px 10px rgba(42,26,21,.25))}\n.seal-bg{fill:var(--espresso)} .seal-in{fill:var(--pink)}\n.seal text{fill:var(--cream);font:800 10px var(--sans);letter-spacing:2.1px}\n.seal-spin{transform-origin:60px 60px;animation:spin 18s linear infinite}\n.seal-mid{fill:var(--espresso)!important;font:italic 600 15px var(--serif)!important;letter-spacing:1px!important}\n@keyframes spin{to{transform:rotate(360deg)}}\n@media (max-width:380px){.seal{right:-6px;width:80px}}\n.when-line{text-align:center;font-size:.86rem;color:var(--muted);display:flex;flex-direction:column;margin-top:30px}\n.when-line span:first-child{font-weight:700;color:var(--ink)}\n\n.soon{background:var(--paper);border:1.5px dashed var(--rose);border-radius:16px;padding:16px;display:flex;flex-direction:column;gap:6px;transform:rotate(-1deg)}\n\n/* Form */\nform{position:relative;z-index:3;background:var(--paper);border:2px solid var(--espresso);border-radius:22px;padding:18px 18px 16px;display:flex;flex-direction:column;gap:12px;\n  box-shadow:8px 8px 0 var(--pink);margin-top:8px}\n.form-head{display:flex;justify-content:space-between;align-items:center}\n.form-head .label{color:var(--rose)}\n.free{font-family:var(--hand);font-weight:700;font-size:1.25rem;line-height:1.2;color:var(--espresso);background:var(--pink);padding:0 10px 2px;border-radius:6px;transform:rotate(4deg)}\nform h2{font-family:var(--serif);text-transform:none;letter-spacing:-.01em;font-weight:600;font-size:1.7rem;margin-top:-4px}\n.field{display:flex;flex-direction:column;gap:5px;font-size:.72rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.field input,.field select,.field textarea{font:500 1rem var(--sans);letter-spacing:0;text-transform:none;color:var(--ink);background:var(--cream);border:1.5px solid var(--line);border-radius:12px;padding:13px 14px;width:100%}\n.field textarea{min-height:80px;resize:vertical}\n.field input::placeholder,.field textarea::placeholder{color:#B4A199}\n.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--espresso);box-shadow:0 0 0 3px var(--pink-2)}\ndetails.more summary{cursor:pointer;font-size:.88rem;font-weight:700;list-style:none;display:flex;align-items:center;gap:8px}\ndetails.more summary::-webkit-details-marker{display:none}\ndetails.more summary::before{content:\"+\";display:grid;place-items:center;width:20px;height:20px;border-radius:50%;border:1.5px solid var(--espresso);font-weight:800;font-size:.8rem}\ndetails.more[open] summary::before{content:\"–\"}\n.opt{font-weight:500;color:var(--muted)}\n.more-body{display:flex;flex-direction:column;gap:12px;margin-top:12px}\n.check{display:flex;gap:10px;align-items:flex-start;font-size:.85rem;color:var(--muted)}\n.check input{accent-color:var(--espresso);width:18px;height:18px;margin-top:2px;flex:none}\n.err{color:var(--err);font-size:.82rem;font-weight:600;letter-spacing:0;text-transform:none}\n.err:empty{display:none}\n.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}\n.fine{font-size:.78rem;color:var(--muted);text-align:center}\n.fine.light{color:var(--pink-2)}\n\n/* CTA */\n.cta{position:relative;display:flex;align-items:center;justify-content:center;gap:10px;width:100%;font:800 .95rem var(--sans);letter-spacing:.2em;text-transform:uppercase;text-decoration:none;\n  color:var(--cream);background:var(--espresso);border:0;border-radius:999px;padding:18px 22px;cursor:pointer;box-shadow:0 10px 24px -8px rgba(59,38,33,.6),inset 0 1px 0 rgba(255,255,255,.12);overflow:hidden}\n.cta svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;transition:transform .2s}\n.cta:hover svg{transform:translateX(3px)}\n.cta::after{content:\"\";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(244,166,196,.35) 50%,transparent 70%);transform:translateX(-100%);animation:shine 3.2s 1.5s infinite}\n@keyframes shine{40%,100%{transform:translateX(100%)}}\n.cta:active{transform:translateY(1px)}\n.cta[disabled]{opacity:.65;cursor:wait}\n.cta.light,.cta.pink{background:var(--pink);color:var(--espresso);box-shadow:0 10px 30px -8px rgba(244,166,196,.6)}\n.cta:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--rose);outline-offset:3px}\n\n/* ---------- Sections ---------- */\n.sec{max-width:560px;margin:0 auto;padding:56px 16px;display:flex;flex-direction:column;gap:14px}\n.sec.dark{max-width:none;background:var(--espresso);color:var(--cream);padding-left:max(16px,calc(50% - 264px));padding-right:max(16px,calc(50% - 264px));\n  background-image:radial-gradient(120% 60% at 50% 0%,rgba(244,166,196,.18),transparent 60%),radial-gradient(rgba(255,255,255,.05) 1px,transparent 1.2px);background-size:auto,18px 18px}\n.note{font-size:.75rem;color:var(--muted);text-align:center}\n.desc{white-space:pre-line;color:var(--muted)}\n.desc:empty{display:none}\n\n/* DM phone */\n.phone{align-self:center;width:min(100%,330px);background:var(--espresso-2);border-radius:42px;padding:12px;box-shadow:0 30px 50px -20px rgba(42,26,21,.55),inset 0 0 0 2px #5a3a31;margin-top:10px;transform:rotate(1.5deg)}\n.phone-top{height:22px;display:flex;justify-content:center}\n.notch{width:90px;height:22px;background:#000;border-radius:0 0 14px 14px}\n.chat-head{display:flex;align-items:center;gap:10px;background:var(--paper);padding:12px 14px;border-radius:30px 30px 0 0;border-bottom:1px solid var(--line)}\n.chat-head b{display:block;font-size:.85rem}.chat-head small{color:var(--muted);font-size:.7rem}\n.avatar{width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,var(--pink),var(--rose));color:#fff;display:grid;place-items:center;font-weight:800}\n.chat{background:var(--paper);border-radius:0 0 30px 30px;padding:14px 12px 16px;min-height:390px;display:flex;flex-direction:column;gap:8px}\n.msg{max-width:82%;padding:10px 13px;border-radius:18px;font-size:.9rem;line-height:1.4;opacity:0;transform:translateY(10px) scale(.97);transition:all .45s cubic-bezier(.2,1.2,.4,1)}\n.msg.in{background:#EFE7E2;align-self:flex-start;border-bottom-left-radius:5px}\n.msg.out{background:var(--pink);align-self:flex-end;border-bottom-right-radius:5px;color:var(--espresso-2)}\n.srcs{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}\n.srcs i{font-style:normal;font-size:.62rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;background:rgba(255,255,255,.6);padding:2px 7px;border-radius:999px}\n.typing{align-self:flex-end;display:flex;align-items:center;gap:4px;background:var(--blush);border-radius:16px;padding:9px 12px;opacity:0;transition:opacity .3s}\n.typing i{width:6px;height:6px;border-radius:50%;background:var(--rose);animation:dot 1.1s infinite}\n.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}\n.typing span{font-size:.7rem;color:var(--rose);font-weight:700;margin-left:4px}\n@keyframes dot{40%{transform:translateY(-4px);opacity:.4}}\n.approve{align-self:flex-end;display:flex;flex-direction:column;align-items:flex-end;gap:6px;opacity:0;transition:opacity .4s}\n.chip{font-size:.66rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--rose)}\n.approve button{font:800 .78rem var(--sans);letter-spacing:.1em;text-transform:uppercase;background:var(--espresso);color:var(--cream);border:0;border-radius:999px;padding:10px 16px;cursor:pointer;animation:nudge 2s infinite}\n.approve button.sent{background:var(--ok);animation:none}\n@keyframes nudge{50%{box-shadow:0 0 0 6px rgba(244,166,196,.45)}}\n.show{opacity:1!important;transform:none!important}\n\n/* Class menu */\n.menu-card{position:relative;background:var(--paper);border:2px solid var(--espresso);border-radius:6px;padding:20px 18px 18px;box-shadow:0 22px 40px -22px rgba(42,26,21,.5);margin-top:6px}\n.menu-card::before{content:\"\";position:absolute;inset:6px;border:1px solid var(--line);border-radius:3px;pointer-events:none}\n.menu-head{display:flex;gap:10px;align-items:center;border-bottom:2px solid var(--espresso);padding-bottom:12px;margin-bottom:8px}\n.menu-head b{font-family:var(--serif);font-style:italic;font-size:1.35rem;font-weight:600;display:block;line-height:1}\n.menu-head small{font-size:.66rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.menu{list-style:none;margin:0;padding:0}\n.menu li{display:grid;grid-template-columns:28px 1fr auto;grid-template-rows:auto auto;column-gap:8px;padding:12px 0;border-bottom:1px dashed var(--line)}\n.m-n{font-family:var(--hand);font-size:1.4rem;color:var(--rose);font-weight:700;line-height:1}\n.m-t b{font-weight:800;font-size:.98rem}\n.m-t small{display:block;color:var(--muted);font-size:.84rem;margin-top:2px}\n.menu li .m-dots{display:none}\n.m-p{font-family:var(--hand);font-size:1.15rem;color:var(--espresso);font-weight:700;align-self:start}\n.menu-total{display:flex;align-items:baseline;gap:8px;padding-top:14px;font-size:.75rem;font-weight:800;letter-spacing:.2em;text-transform:uppercase}\n.menu-total .m-dots{flex:1;border-bottom:2px dotted var(--espresso);transform:translateY(-4px)}\n.menu-total b{font-family:var(--serif);font-size:1.9rem;letter-spacing:0;color:var(--rose);font-style:italic}\n.menu-foot{text-align:center;font-family:var(--hand);font-size:1.15rem;color:var(--muted);margin-top:4px}\n\n/* How it works (dark windows) */\n.flow{display:flex;flex-direction:column;gap:18px;margin-top:10px;position:relative}\n.flow::before{content:\"\";position:absolute;left:50%;top:10px;bottom:10px;border-left:2px dashed rgba(244,166,196,.35)}\n.win{position:relative;background:linear-gradient(180deg,#4A302A,#3B2621);border:1px solid rgba(244,166,196,.25);border-radius:18px;overflow:hidden;box-shadow:0 20px 40px -20px rgba(0,0,0,.6)}\n.win header{display:flex;align-items:center;gap:5px;padding:10px 14px;border-bottom:1px solid rgba(244,166,196,.15)}\n.win header i{width:8px;height:8px;border-radius:50%;background:var(--pink);opacity:.9}.win header i+i{opacity:.55}.win header i+i+i{opacity:.3}\n.win header span{margin-left:auto;font-size:.62rem;font-weight:800;letter-spacing:.2em;text-transform:uppercase;color:var(--pink-2)}\n.win-body{padding:16px;display:grid;grid-template-columns:1fr auto;gap:6px 12px}\n.win .big{font-family:var(--serif);font-size:2.6rem;line-height:1;color:var(--pink);font-style:italic}\n.ico{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:rgba(244,166,196,.12);border:1px solid rgba(244,166,196,.4);box-shadow:0 0 20px rgba(244,166,196,.25)}\n.ico svg{width:22px;height:22px;fill:none;stroke:var(--pink);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.win h3{grid-column:1/-1;font-size:1.1rem;font-weight:800;color:var(--cream)}\n.win p{grid-column:1/-1;color:#D9C5BE;font-size:.92rem}\n.status{grid-column:1/-1;display:flex;align-items:center;gap:8px;margin-top:6px;font-size:.74rem;color:#E9D7D0;border:1px solid rgba(244,166,196,.25);border-radius:999px;padding:6px 12px;background:rgba(0,0,0,.15)}\n.pulse{width:7px;height:7px;border-radius:50%;background:var(--pink);animation:blink 1.2s infinite}\n.bar{margin-left:auto;width:54px;height:4px;border-radius:4px;background:rgba(255,255,255,.12);overflow:hidden}\n.bar i{display:block;height:100%;width:0;background:var(--pink);border-radius:4px;transition:width 1.6s ease}\n.win.show .bar i{width:var(--w)}\n.reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}\n.pull{font-family:var(--serif);font-size:1.6rem;line-height:1.15;text-align:center;margin:18px 0 6px;color:var(--cream)}\n.pull em{display:block;color:var(--pink)}\n\n/* Before / after */\n.ba{display:flex;flex-direction:column;gap:12px;margin-top:6px}\n.ba-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.ba-row>div{border-radius:14px;padding:12px;font-size:.9rem;font-weight:600;line-height:1.35}\n.ba small{display:block;font-size:.6rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;margin-bottom:4px}\n.ba-b{background:var(--tan);color:var(--muted);transform:rotate(-1deg)}\n.ba-b s{text-decoration-color:rgba(162,77,110,.7);text-decoration-thickness:2px}\n.ba-b small{color:var(--muted)}\n.ba-b small::before{content:\"✕ \"}\n.ba-a{background:var(--espresso);color:var(--cream);transform:rotate(1deg);box-shadow:4px 4px 0 var(--pink)}\n.ba-a small{color:var(--pink)} .ba-a small::before{content:\"✓ \"}\n\n/* Sticky notes */\n.tapnote{font-family:var(--hand);font-size:1.25rem;color:var(--muted);display:flex;align-items:center;gap:6px}\n.tapnote svg{width:36px;height:18px;fill:none;stroke:var(--muted);stroke-width:1.8;stroke-linecap:round}\n.notes{display:flex;flex-direction:column;gap:14px;margin-top:4px}\n.note-card{position:relative;display:flex;gap:12px;align-items:center;text-align:left;font:700 1.35rem/1.15 var(--hand);color:var(--espresso);border:0;cursor:pointer;\n  padding:18px 16px 16px;border-radius:2px 2px 14px 2px;background:var(--blush);box-shadow:0 10px 18px -12px rgba(42,26,21,.55);transition:transform .25s,background .25s}\n.note-card:nth-child(odd){transform:rotate(-1.4deg)} .note-card:nth-child(even){transform:rotate(1.2deg);background:#F5ECDD}\n.note-card::before{content:\"\";position:absolute;top:-9px;left:50%;width:70px;height:18px;margin-left:-35px;background:rgba(244,166,196,.55);transform:rotate(-3deg)}\n.note-card .box{flex:none;width:26px;height:26px;border:2.5px solid var(--espresso);border-radius:6px;display:grid;place-items:center}\n.note-card[aria-pressed=\"true\"]{background:var(--pink);transform:rotate(0) scale(1.02)}\n.note-card[aria-pressed=\"true\"] .box::after{content:\"\";width:12px;height:7px;border-left:3px solid var(--espresso);border-bottom:3px solid var(--espresso);transform:rotate(-45deg) translate(1px,-2px);animation:pop .3s}\n@keyframes pop{0%{transform:rotate(-45deg) scale(0)}}\n.tally{text-align:center;font-family:var(--hand);font-size:1.35rem;color:var(--rose);min-height:1.5em}\n\n/* Host */\n.host-card{background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:18px;display:flex;flex-direction:column;gap:10px;box-shadow:0 22px 40px -26px rgba(42,26,21,.5)}\n.ab-card{aspect-ratio:1.55;border-radius:18px;background:linear-gradient(135deg,#F7C3D7,#EBA9C0 55%,#E5B7A9);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;position:relative;overflow:hidden;\n  box-shadow:inset 0 0 0 8px rgba(255,255,255,.25)}\n.ab-card::after{content:\"\";position:absolute;inset:-40%;background:linear-gradient(115deg,transparent 40%,rgba(255,255,255,.45) 50%,transparent 60%);animation:sheen 5s infinite}\n@keyframes sheen{0%{transform:translateX(-60%)}60%,100%{transform:translateX(60%)}}\n.ab{font-family:var(--serif);font-style:italic;font-size:5rem;line-height:1;color:var(--espresso)}\n.ab-cap{font-size:.62rem;font-weight:800;letter-spacing:.3em;text-transform:uppercase;color:var(--espresso)}\n.host .display{font-size:2.3rem}\n.host .display em{display:inline}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chips span{font-size:.68rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;border:1.5px solid var(--espresso);border-radius:999px;padding:5px 10px}\n.sig{font-family:var(--hand);font-size:1.6rem;color:var(--rose);font-weight:700;margin-top:4px}\n\n/* Final */\n.final{max-width:none;margin:0;background:var(--espresso);color:var(--cream);text-align:center;align-items:center;padding:60px 16px 64px;\n  background-image:radial-gradient(90% 50% at 50% 0%,rgba(244,166,196,.22),transparent 60%)}\n.final .display em{display:inline}\n.final-date{font-family:var(--serif);font-size:1.3rem}\n.zones{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;max-width:420px}\n.zones span{font-size:.8rem;border:1px solid rgba(244,166,196,.45);border-radius:999px;padding:6px 12px;color:var(--pink-2)}\n.zones span b{color:var(--cream)}\n.zones span.you{background:var(--pink);color:var(--espresso);border-color:var(--pink)}\n.zones span.you b{color:var(--espresso)}\n.final .cta{max-width:420px}\n.livenow{font-weight:800;text-transform:uppercase;letter-spacing:.2em;color:var(--pink)}\n\n.foot{text-align:center;padding:36px 16px 90px;display:flex;flex-direction:column;align-items:center;gap:8px;color:var(--muted)}\n.foot p{font-family:var(--serif);font-style:italic;font-size:1.1rem;color:var(--ink)}\n.foot .small{font-family:var(--sans);font-style:normal;font-size:.8rem;color:var(--muted)}\n\n/* Floating CTA (phone) */\n.float-cta{position:fixed;left:50%;bottom:max(14px,env(safe-area-inset-bottom));transform:translateX(-50%);z-index:40;background:var(--espresso);color:var(--cream);text-decoration:none;\n  font:800 .8rem var(--sans);letter-spacing:.18em;text-transform:uppercase;padding:14px 26px;border-radius:999px;box-shadow:0 12px 30px -8px rgba(42,26,21,.7),0 0 0 3px var(--pink);animation:rise .4s ease}\n@keyframes rise{from{transform:translate(-50%,30px);opacity:0}}\n\n/* Desktop: wider hero with form beside the date */\n@media (min-width:900px){\n  .hero{max-width:1080px;display:grid;grid-template-columns:1.1fr .9fr;column-gap:56px;align-items:start;padding-top:48px}\n  .hero>*{grid-column:1}\n  .hero form,.hero #waitlist{grid-column:2;grid-row:1 / span 8;position:sticky;top:calc(var(--top) + 20px)}\n  .datewrap{align-items:flex-start}.seal{right:auto;left:178px;bottom:-34px}\n  .when-line{text-align:left}\n  .prop-polish{right:auto;left:47%;top:60px}.prop-file{right:auto;left:49%;top:470px}.prop-nail{left:36%;top:640px}.prop-spark.s2{left:30%;top:560px}\n  .sec{max-width:640px}\n  .float-cta{display:none}\n}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.reveal,.msg,.typing,.approve{opacity:1;transform:none}.swoosh path{stroke-dashoffset:0}}\n\n/* ---------- Thank-you page ---------- */\n.center{text-align:center}\n.ty-hero{padding-bottom:28px}\n.ty-hero h1{font-size:clamp(3rem,14vw,4.6rem)}\n.ty-hero h1 em{display:inline}\n.appt{position:relative;background:var(--paper);border:2px solid var(--espresso);border-radius:20px;padding:18px 18px 14px;box-shadow:10px 10px 0 var(--espresso);\n  transform:rotate(-1.6deg);margin:14px 6px 18px;animation:land .7s cubic-bezier(.2,1.3,.4,1)}\n@keyframes land{from{transform:rotate(-8deg) translateY(30px) scale(.94);opacity:0}}\n.appt-top{display:flex;align-items:center;gap:10px;border-bottom:2px solid var(--espresso);padding-bottom:12px;margin-bottom:4px}\n.appt-top b{display:block;font-family:var(--serif);font-style:italic;font-size:1.25rem;line-height:1}\n.appt-top small{font-size:.62rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}\n.appt-free{margin-left:auto;font-family:var(--hand);font-weight:700;font-size:1.2rem;background:var(--pink);padding:0 10px 2px;border-radius:6px;transform:rotate(4deg)}\n.appt-row{display:flex;align-items:baseline;gap:12px;border-bottom:1.5px dashed var(--line);padding:9px 2px 5px}\n.appt-row span{width:62px;flex:none;font-size:.62rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}\n.appt-row b{font-family:var(--hand);font-size:1.55rem;line-height:1.1;color:var(--rose);font-weight:700}\n.appt-foot{display:flex;justify-content:space-between;padding-top:10px;font-size:.62rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}\n.stamp{position:absolute;right:14px;bottom:46px;border:3px solid var(--rose);color:var(--rose);border-radius:8px;padding:4px 10px;font-weight:800;font-size:.9rem;letter-spacing:.18em;text-transform:uppercase;\n  transform:rotate(-14deg);opacity:.85;mix-blend-mode:multiply;animation:stampin .5s .6s cubic-bezier(.2,1.6,.4,1) both}\n@keyframes stampin{from{transform:rotate(-14deg) scale(2.2);opacity:0}}\n.ty-steps{gap:16px}\n.step-card{display:grid;grid-template-columns:auto 1fr;gap:14px;background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:18px 16px;box-shadow:0 18px 34px -24px rgba(42,26,21,.5)}\n.step-n{font-family:var(--serif);font-style:italic;font-size:2.2rem;line-height:1;color:var(--espresso);background:var(--pink);border-radius:14px;width:58px;height:58px;display:grid;place-items:center}\n.step-card h3{font-size:1.1rem;font-weight:800;margin-bottom:4px}\n.step-card p{color:var(--muted);font-size:.93rem}\n.cal-btns,.pick{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}\n.pill,.pick button{font:700 .82rem var(--sans);color:var(--espresso);text-decoration:none;border:1.5px solid var(--espresso);border-radius:999px;padding:9px 14px;background:var(--paper);cursor:pointer}\n.pill:hover{background:var(--blush)}\n.pick button[aria-pressed=\"true\"]{background:var(--espresso);color:var(--cream)}\n.script.small{font-size:1.25rem;margin-top:8px}\n.sig.center{font-size:1.8rem;margin-top:10px}\n.thanks .prop-polish{top:14px;width:44px;right:6px}\n.thanks .lead{max-width:30ch}\n#story{letter-spacing:.12em;font-size:.85rem}\n\n/* Host photo */\n.polaroid{position:relative;margin:4px 6px 8px;background:#fff;padding:12px 12px 0;border-radius:4px;transform:rotate(-2deg);box-shadow:0 22px 36px -18px rgba(42,26,21,.55)}\n.polaroid img{display:block;width:100%;height:auto;aspect-ratio:1;object-fit:cover;object-position:50% 20%;border-radius:2px;max-width:100%}\n.polaroid figcaption{font-family:var(--hand);font-size:1.5rem;color:var(--espresso);text-align:center;padding:8px 0 12px}\n.tape{position:absolute;top:-12px;left:50%;width:96px;height:24px;margin-left:-48px;background:rgba(244,166,196,.7);transform:rotate(3deg);z-index:1}\n.signoff-row{display:flex;align-items:center;justify-content:center;gap:14px;margin-top:10px}\n.signoff-row img{width:64px;height:64px;border-radius:50%;object-fit:cover;border:3px solid var(--pink)}\n.signoff-row .sig{font-size:1.7rem;margin:0}\n\n"},"app.js":{"t":"text/javascript; charset=utf-8","b":"(function () {\n  var $ = function (id) { return document.getElementById(id); };\n  var events = [], current = null, timer = null, last = {};\n  var mine = \"\";\n  try { mine = Intl.DateTimeFormat().resolvedOptions().timeZone || \"\"; $(\"tz\").value = mine; } catch (e) {}\n  var params = new URLSearchParams(location.search);\n  $(\"ref\").value = (params.get(\"src\") || params.get(\"utm_source\") || \"\").slice(0, 60);\n  var reduce = window.matchMedia && matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n\n  function fmtParts(iso, tz, o) { return new Intl.DateTimeFormat(\"en-US\", Object.assign({ timeZone: tz }, o)).format(new Date(iso)); }\n  function fmt(iso, tz, withZone) {\n    return fmtParts(iso, tz, { weekday: \"long\", month: \"long\", day: \"numeric\" }) + \" at \" +\n      fmtParts(iso, tz, { hour: \"numeric\", minute: \"2-digit\", timeZoneName: withZone ? \"short\" : undefined });\n  }\n  function time(iso, tz) { return fmtParts(iso, tz, { hour: \"numeric\", minute: \"2-digit\", timeZoneName: \"short\" }).replace(\":00\", \"\"); }\n\n  // ---------- Ticker ----------\n  function setTicker(items) {\n    var t = $(\"ticker\"); t.textContent = \"\";\n    for (var r = 0; r < 2; r++) {\n      var s = document.createElement(\"span\");\n      for (var rep = 0; rep < 2; rep++) items.forEach(function (x, i) { var b = document.createElement(i % 2 ? \"b\" : \"span\"); b.textContent = x + \" · \"; s.appendChild(b); });\n      t.appendChild(s);\n    }\n  }\n\n  // ---------- Flip countdown ----------\n  function buildFlip(box) {\n    box.textContent = \"\";\n    [\"Days\", \"Hrs\", \"Min\", \"Sec\"].forEach(function (u, i) {\n      if (i) { var c = document.createElement(\"span\"); c.className = \"colon\"; c.textContent = \":\"; box.appendChild(c); }\n      var unit = document.createElement(\"div\"); unit.className = \"unit\";\n      var pair = document.createElement(\"div\"); pair.className = \"pair\";\n      for (var k = 0; k < 2; k++) { var d = document.createElement(\"span\"); d.className = \"d\"; d.textContent = \"0\"; pair.appendChild(d); }\n      var lab = document.createElement(\"span\"); lab.className = \"u\"; lab.textContent = u;\n      unit.appendChild(pair); unit.appendChild(lab); box.appendChild(unit);\n    });\n  }\n  function tick() {\n    if (!current) return;\n    var ms = new Date(current.startUtc).getTime() - Date.now();\n    [\"flip1\", \"flip2\"].forEach(function (id) {\n      var box = $(id);\n      if (ms <= 0) { box.innerHTML = '<p class=\"livenow\">We\\'re live now</p>'; return; }\n      if (!box.querySelector(\".d\")) buildFlip(box);\n      var s = Math.floor(ms / 1000);\n      var str = [Math.min(99, Math.floor(s / 86400)), Math.floor(s % 86400 / 3600), Math.floor(s % 3600 / 60), s % 60]\n        .map(function (n) { return String(n).padStart(2, \"0\"); }).join(\"\");\n      var ds = box.querySelectorAll(\".d\");\n      for (var i = 0; i < ds.length; i++) {\n        if (ds[i].textContent !== str[i]) {\n          ds[i].textContent = str[i];\n          if (!reduce && last[id]) { ds[i].classList.remove(\"flip-in\"); void ds[i].offsetWidth; ds[i].classList.add(\"flip-in\"); }\n        }\n      }\n      last[id] = true;\n    });\n  }\n\n  // ---------- Show a session ----------\n  function show(ev) {\n    current = ev;\n    $(\"eventId\").value = ev.id;\n    $(\"title\").textContent = ev.title;\n    var zone = mine || ev.tz;\n    $(\"calMonth\").textContent = fmtParts(ev.startUtc, zone, { month: \"short\" });\n    $(\"calDay\").textContent = fmtParts(ev.startUtc, zone, { day: \"numeric\" });\n    $(\"calWeekday\").textContent = fmtParts(ev.startUtc, zone, { weekday: \"long\" });\n    $(\"calTime\").textContent = time(ev.startUtc, zone);\n    $(\"when\").textContent = fmt(ev.startUtc, ev.tz, true) + \" · \" + (ev.durationMin || 45) + \" min on Zoom\";\n    $(\"localwhen\").textContent = mine && mine !== ev.tz ? \"That's \" + fmt(ev.startUtc, mine, true) + \" where you are\" : \"\";\n    $(\"whenline\").hidden = false;\n    $(\"finalWhen\").textContent = fmt(ev.startUtc, zone, true);\n    $(\"menuFoot\").textContent = (ev.durationMin || 45) + \" min · live on Zoom · bring your phone\";\n    $(\"desc\").textContent = ev.description || \"\";\n    var zones = $(\"zones\"); zones.textContent = \"\";\n    [[\"America/Los_Angeles\", \"PT\"], [\"America/Denver\", \"MT\"], [\"America/Chicago\", \"CT\"], [\"America/New_York\", \"ET\"]].forEach(function (z) {\n      var s = document.createElement(\"span\"); var b = document.createElement(\"b\");\n      b.textContent = fmtParts(ev.startUtc, z[0], { hour: \"numeric\", minute: \"2-digit\" }).replace(\":00\", \"\");\n      s.appendChild(b); s.appendChild(document.createTextNode(\" \" + z[1]));\n      if (fmtParts(ev.startUtc, z[0], { timeZoneName: \"short\" }) === fmtParts(ev.startUtc, zone, { timeZoneName: \"short\" })) s.className = \"you\";\n      zones.appendChild(s);\n    });\n    $(\"final\").hidden = false; $(\"clockbar\").hidden = false;\n    setTicker([\"Free live class\", ev.title, fmtParts(ev.startUtc, ev.tz, { weekday: \"short\", month: \"short\", day: \"numeric\" }), time(ev.startUtc, ev.tz), \"Live on Zoom\", \"Bring your DMs\"]);\n    document.title = ev.title + \" | Free Live Class with The Nail Bawse\";\n    Array.prototype.forEach.call($(\"picker\").children, function (b) { b.setAttribute(\"aria-pressed\", String(b.dataset.id === ev.id)); });\n    tick(); if (!timer) timer = setInterval(tick, 1000);\n  }\n\n  setTicker([\"Free live class\", \"Build Your AI Agent\", \"For beauty pros\", \"Live on Zoom\", \"Bring your DMs\"]);\n\n  fetch(\"/api/events\").then(function (r) { return r.json(); }).then(function (data) {\n    events = (data && data.events) || [];\n    var wanted = params.get(\"s\");\n    if (!events.length) {\n      $(\"waitlist\").hidden = false; $(\"formtitle\").textContent = \"Get the next date\"; $(\"submitText\").textContent = \"Notify me\";\n      document.querySelectorAll(\"[data-cta] span, .float-cta\").forEach(function (a) { if (!a.children.length) a.textContent = \"Notify me\"; });\n      return;\n    }\n    $(\"session\").hidden = false;\n    if (events.length > 1) {\n      events.forEach(function (ev) {\n        var b = document.createElement(\"button\");\n        b.type = \"button\"; b.dataset.id = ev.id;\n        b.textContent = fmtParts(ev.startUtc, ev.tz, { weekday: \"short\", month: \"short\", day: \"numeric\" });\n        b.addEventListener(\"click\", function () { show(ev); });\n        $(\"picker\").appendChild(b);\n      });\n    }\n    show(events.find(function (e) { return e.id === wanted; }) || events[0]);\n  }).catch(function () { $(\"waitlist\").hidden = false; });\n\n  // ---------- CTAs scroll to form ----------\n  document.querySelectorAll(\"[data-cta]\").forEach(function (a) {\n    a.addEventListener(\"click\", function (e) { e.preventDefault(); $(\"reg\").scrollIntoView({ behavior: reduce ? \"auto\" : \"smooth\", block: \"start\" }); setTimeout(function () { $(\"firstName\").focus({ preventScroll: true }); }, 450); });\n  });\n\n  // ---------- Floating CTA when the form is off screen ----------\n  if (\"IntersectionObserver\" in window) {\n    var formSeen = true, heroGone = false;\n    var upd = function () { $(\"floatCta\").hidden = formSeen || !heroGone; };\n    new IntersectionObserver(function (es) { formSeen = es[0].isIntersecting; upd(); }).observe($(\"reg\"));\n    new IntersectionObserver(function (es) { heroGone = !es[0].isIntersecting; upd(); }).observe(document.querySelector(\".hero\"));\n  }\n\n  // ---------- Reveal on scroll + DM demo ----------\n  var chatPlayed = false;\n  function playChat() {\n    if (chatPlayed) return; chatPlayed = true;\n    var steps = document.querySelectorAll(\"#chat [data-step]\");\n    var at = [200, 1100, 2000, 3600, 4400];\n    steps.forEach(function (el, i) {\n      setTimeout(function () {\n        el.classList.add(\"show\");\n        if (el.classList.contains(\"typing\")) setTimeout(function () { el.style.display = \"none\"; }, 1500);\n      }, reduce ? 0 : at[i]);\n    });\n  }\n  document.querySelectorAll(\".win\").forEach(function (w) { w.classList.add(\"reveal\"); });\n  if (\"IntersectionObserver\" in window) {\n    var io = new IntersectionObserver(function (es) {\n      es.forEach(function (e) {\n        if (!e.isIntersecting) return;\n        if (e.target.id === \"dmPhone\") playChat(); else e.target.classList.add(\"show\");\n        io.unobserve(e.target);\n      });\n    }, { threshold: 0.3 });\n    io.observe($(\"dmPhone\")); document.querySelectorAll(\".reveal\").forEach(function (el) { io.observe(el); });\n  } else { playChat(); document.querySelectorAll(\".reveal\").forEach(function (el) { el.classList.add(\"show\"); }); }\n  $(\"approveBtn\").addEventListener(\"click\", function () { this.textContent = \"Sent ✓\"; this.classList.add(\"sent\"); this.previousElementSibling.textContent = \"Approved by you\"; });\n\n  // ---------- Sticky notes ----------\n  var notes = document.querySelectorAll(\".note-card\");\n  notes.forEach(function (n) {\n    n.addEventListener(\"click\", function () {\n      n.setAttribute(\"aria-pressed\", String(n.getAttribute(\"aria-pressed\") !== \"true\"));\n      var c = document.querySelectorAll('.note-card[aria-pressed=\"true\"]').length;\n      $(\"tally\").textContent = c === 0 ? \"\" : c >= 3 ? \"Okay, this class was made for you. Save your seat ↑\" : c + \" of 5. Sounds like you need an agent.\";\n    });\n  });\n\n  // ---------- Submit ----------\n  $(\"reg\").addEventListener(\"submit\", function (e) {\n    e.preventDefault();\n    document.querySelectorAll(\".err\").forEach(function (el) { el.textContent = \"\"; });\n    var f = new FormData($(\"reg\"));\n    var body = {}; f.forEach(function (v, k) { body[k] = v; });\n    body.optIn = $(\"optIn\").checked;\n    $(\"submit\").disabled = true; $(\"submitText\").textContent = \"Saving…\";\n    fetch(\"/api/register\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(body) })\n      .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })\n      .then(function (res) {\n        if (res.ok) {\n          location.href = (document.documentElement.getAttribute(\"data-thanks\") || \"/thanks.html\") + \"?e=\" + encodeURIComponent(res.j.eventId) + (res.j.emailed ? \"\" : \"&m=0\") + \"&n=\" + encodeURIComponent((body.firstName || \"\").slice(0, 30));\n          return;\n        }\n        var fields = res.j.fields || {};\n        if (fields.phone) $(\"reg\").querySelector(\"details\").open = true;\n        Object.keys(fields).forEach(function (k) { var el = document.querySelector('.err[data-for=\"' + k + '\"]'); if (el) el.textContent = fields[k]; });\n        document.querySelector('.err[data-for=\"form\"]').textContent = res.j.error || \"Something went wrong. Please try again.\";\n      })\n      .catch(function () { document.querySelector('.err[data-for=\"form\"]').textContent = \"Couldn't reach the server. Check your connection and try again.\"; })\n      .finally(function () { $(\"submit\").disabled = false; $(\"submitText\").textContent = current ? \"Save my seat\" : \"Notify me\"; });\n  });\n})();\n"},"card.js":{"t":"text/javascript; charset=utf-8","b":"/* The Nail Bawse appointment card as a 1080x1920 story picture.\n   It redraws the card shown on the thank-you page (same layout, colors and type).\n   NBCard.draw({ name, title, date, time }) -> Promise<HTMLCanvasElement> */\n(function () {\n  var C = { espresso: \"#3B2621\", ink: \"#2A1A15\", cream: \"#FBF6F1\", paper: \"#FFFDFB\", pink: \"#F4A6C4\", rose: \"#A24D6E\", muted: \"#76605A\", line: \"#E7D8CE\" };\n  var SERIF = \"Fraunces, Georgia, serif\", SANS = \"Inter, Arial, sans-serif\", HAND = \"Caveat, 'Segoe Print', cursive\";\n\n  function fontsReady() {\n    if (!document.fonts || !document.fonts.load) return Promise.resolve();\n    return Promise.all([\"400 100px Fraunces\", \"italic 400 100px Fraunces\", \"italic 600 100px Fraunces\", \"700 100px Caveat\", \"800 40px Inter\"]\n      .map(function (f) { return document.fonts.load(f).catch(function () {}); })).then(function () { return document.fonts.ready; });\n  }\n  function rr(g, x, y, w, h, r) { g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); }\n  function caps(g, text, x, y, sp, align) {\n    var w = 0, i; for (i = 0; i < text.length; i++) w += g.measureText(text[i]).width + (i < text.length - 1 ? sp : 0);\n    var cx = align === \"center\" ? x - w / 2 : align === \"right\" ? x - w : x;\n    var ta = g.textAlign; g.textAlign = \"left\";\n    for (i = 0; i < text.length; i++) { g.fillText(text[i], cx, y); cx += g.measureText(text[i]).width + sp; }\n    g.textAlign = ta; return w;\n  }\n  function fit(g, text, font, size, max, min) { do { g.font = font.replace(\"{s}\", size); if (g.measureText(text).width <= max) break; size -= 2; } while (size > min); return size; }\n\n  function draw(d) {\n    return fontsReady().then(function () {\n      var c = document.createElement(\"canvas\"); c.width = 1080; c.height = 1920;\n      var g = c.getContext(\"2d\");\n\n      // Page background: cream with the site's dot grid\n      g.fillStyle = C.cream; g.fillRect(0, 0, 1080, 1920);\n      g.fillStyle = \"rgba(59,38,33,.08)\";\n      for (var x = 22; x < 1080; x += 44) for (var y = 22; y < 1920; y += 44) { g.beginPath(); g.arc(x, y, 2.6, 0, 7); g.fill(); }\n\n      // Brand line + headline, as on the thank-you page\n      g.font = \"800 30px \" + SANS; var bw = 76 + 20 + caps({ measureText: g.measureText.bind(g), fillText: function () {}, textAlign: \"left\" }, \"THE NAIL BAWSE\", 0, 0, 6);\n      var bx = 540 - bw / 2;\n      g.fillStyle = C.espresso; rr(g, bx, 150, 76, 76, 18); g.fill();\n      g.fillStyle = C.cream; g.textAlign = \"center\"; g.font = \"italic 400 38px \" + SERIF; g.fillText(\"NB\", bx + 38, 202);\n      g.textAlign = \"left\"; g.fillStyle = C.ink; g.font = \"800 30px \" + SANS; caps(g, \"THE NAIL BAWSE\", bx + 96, 198, 6);\n      g.font = \"400 150px \" + SERIF; var w1 = g.measureText(\"You're \").width;\n      g.font = \"italic 400 150px \" + SERIF; var w2 = g.measureText(\"booked.\").width;\n      var sx = 540 - (w1 + w2) / 2;\n      g.fillStyle = C.ink; g.font = \"400 150px \" + SERIF; g.fillText(\"You're \", sx, 410);\n      g.fillStyle = C.rose; g.font = \"italic 400 150px \" + SERIF; g.fillText(\"booked.\", sx + w1, 410);\n\n      // ---- The appointment card ----\n      var W = 900, H = 960, X = -W / 2, P = 56;\n      g.save(); g.translate(540, 520); g.rotate(-0.028);\n      g.fillStyle = C.espresso; rr(g, X + 26, 26, W, H, 52); g.fill();          // offset shadow, as on the page\n      g.fillStyle = C.paper; rr(g, X, 0, W, H, 52); g.fill();\n      g.strokeStyle = C.espresso; g.lineWidth = 5; rr(g, X, 0, W, H, 52); g.stroke();\n\n      // header\n      g.fillStyle = C.espresso; rr(g, X + P, 50, 84, 84, 22); g.fill();\n      g.fillStyle = C.cream; g.textAlign = \"center\"; g.font = \"italic 400 40px \" + SERIF; g.fillText(\"NB\", X + P + 42, 106);\n      g.textAlign = \"left\"; g.fillStyle = C.ink; g.font = \"italic 600 62px \" + SERIF; g.fillText(\"The Nail Bawse\", X + P + 112, 104);\n      g.fillStyle = C.muted; g.font = \"800 24px \" + SANS; caps(g, \"APPOINTMENT CARD\", X + P + 114, 142, 6);\n      g.save(); g.translate(-X - P - 70, 92); g.rotate(0.07);\n      g.fillStyle = C.pink; rr(g, -70, -38, 140, 76, 16); g.fill();\n      g.fillStyle = C.espresso; g.textAlign = \"center\"; g.font = \"700 60px \" + HAND; g.fillText(\"Free\", 0, 20); g.restore();\n      g.fillStyle = C.espresso; g.fillRect(X + P, 178, W - 2 * P, 5);\n\n      // rows\n      var rows = [[\"FOR\", d.name || \"You\"], [\"SERVICE\", d.title || \"Build Your AI Agent\"], [\"DATE\", d.date || \"\"], [\"TIME\", d.time || \"\"], [\"WITH\", \"Anisia\"]];\n      rows.forEach(function (r, i) {\n        var ry = 290 + i * 122;\n        g.fillStyle = C.muted; g.font = \"800 25px \" + SANS; g.textAlign = \"left\"; caps(g, r[0], X + P + 4, ry, 5);\n        var s = fit(g, r[1], \"700 {s}px \" + HAND, 80, W - 2 * P - 200, 44);\n        g.fillStyle = C.rose; g.font = \"700 \" + s + \"px \" + HAND; g.fillText(r[1], X + P + 196, ry + 8);\n        g.strokeStyle = C.line; g.lineWidth = 4; g.setLineDash([14, 10]); g.beginPath(); g.moveTo(X + P, ry + 40); g.lineTo(-X - P, ry + 40); g.stroke(); g.setLineDash([]);\n      });\n\n      // footer\n      g.fillStyle = C.ink; g.font = \"800 25px \" + SANS;\n      caps(g, \"LIVE ON ZOOM\", X + P + 4, H - 56, 6); caps(g, \"@THENAILBAWSE\", -X - P - 4, H - 56, 6, \"right\");\n\n      // stamp\n      g.save(); g.translate(-X - P - 190, H - 200); g.rotate(-0.24); g.globalAlpha = .88;\n      g.strokeStyle = C.rose; g.lineWidth = 7; rr(g, -190, -52, 380, 96, 16); g.stroke();\n      g.fillStyle = C.rose; g.font = \"800 50px \" + SANS; caps(g, \"CONFIRMED\", 0, 18, 8, \"center\"); g.restore();\n      g.restore();\n\n      // ---- Tag line ----\n      g.textAlign = \"center\"; g.fillStyle = C.rose; g.font = \"700 72px \" + HAND; g.fillText(\"free live class with Anisia\", 540, 1640);\n      g.fillStyle = C.espresso; rr(g, 230, 1700, 620, 104, 52); g.fill();\n      g.fillStyle = C.pink; g.font = \"800 38px \" + SANS; caps(g, \"TAG @THENAILBAWSE\", 540, 1766, 5, \"center\");\n      return c;\n    });\n  }\n  window.NBCard = { draw: draw };\n})();\n"},"anisia.jpg":{"t":"image/webp","e":"b64","b":""},"anisia-face.jpg":{"t":"image/webp","e":"b64","b":""}};
const TITLE = "Build Your AI Agent";
const TZ = "America/Los_Angeles";

function bytes(b64) { const s = atob(b64); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
function asset(name, status) {
  const a = ASSETS[name];
  const html = a.t.startsWith("text/html");
  return new Response(a.e === "b64" ? bytes(a.b) : a.b, { status: status || 200, headers: {
    "content-type": a.t, "cache-control": html ? "no-store" : "public, max-age=3600",
    "x-content-type-options": "nosniff", "referrer-policy": "strict-origin-when-cross-origin" } });
}
function json(obj, status) { return new Response(JSON.stringify(obj), { status: status || 200, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } }); }
function evFor(t, h) { return { id: "s" + t, title: TITLE, startUtc: new Date(t).toISOString(), tz: TZ, durationMin: Math.round(h.DUR / 60000), description: "", joinUrl: h.ZOOM }; }
function tFromId(id, h) {
  const m = /^s(\d{12,14})$/.exec(String(id || "")); if (!m) return null;
  const t = Number(m[1]); const n = h.nextSession(t - h.DUR + 1); return n === t ? t : null;
}

export async function funnel(request, env, h) {
  const key = h.key, method = request.method;
  if (key === "/registration") { const u = new URL(request.url); return Response.redirect("https://" + h.APEX + "/webinar" + u.search, 301); }
  if ((key === "/webinar" || key === "/webinar/thanks") && (method === "GET" || method === "HEAD")) return asset(key === "/webinar" ? "index" : "thanks");
  if (h.path.startsWith("/webinar-assets/") && method === "GET") { const n = h.path.slice(16); return ASSETS[n] ? asset(n) : null; }
  if (key === "/api/events" && method === "GET") {
    const id = new URL(request.url).searchParams.get("id");
    if (id) { const t = tFromId(id, h); return t ? json({ event: evFor(t, h) }) : json({ error: "Session not found." }, 404); }
    const next = h.nextSession(Date.now());
    return json({ events: next ? [evFor(next, h)] : [] });
  }
  if (key === "/api/ics" && method === "GET") {
    const t = tFromId(new URL(request.url).searchParams.get("id"), h);
    if (!t) return new Response("Not found", { status: 404 });
    return new Response(h.icsText(t), { headers: { "content-type": "text/calendar; charset=utf-8", "content-disposition": 'attachment; filename="build-your-ai-agent.ics"', "cache-control": "no-store" } });
  }
  if (key === "/api/register" && method === "POST") {
    let b; try { b = await request.json(); } catch (e) { return json({ error: "Something went wrong. Please try again." }, 400); }
    if (String(b.company || "").trim()) return json({ ok: true, eventId: "waitlist", emailed: false });
    const name = String(b.firstName || "").trim().slice(0, 80);
    const email = String(b.email || "").trim().toLowerCase().slice(0, 200);
    const fields = {};
    if (!name) fields.firstName = "Please add your first name.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) fields.email = "Please check your email address.";
    if (Object.keys(fields).length) return json({ error: "Please fix the highlighted fields.", fields: fields }, 400);
    const t = b.eventId && b.eventId !== "waitlist" ? tFromId(b.eventId, h) : h.nextSession(Date.now());
    if (b.eventId && b.eventId !== "waitlist" && !t) return json({ error: "That date has passed. Refresh the page to see the next one." }, 400);
    const optin = b.optIn === false || b.optIn === "false" ? 0 : 1;
    await env.DB.prepare("INSERT INTO signups (created_at, source, first_name, email, marketing_opt_in, session_start_utc, user_agent) VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT(source, email, session_start_utc) DO UPDATE SET first_name = excluded.first_name, marketing_opt_in = MAX(marketing_opt_in, excluded.marketing_opt_in)")
      .bind(new Date().toISOString(), "webinar", name, email, optin, t ? new Date(t).toISOString() : "tba", String(request.headers.get("user-agent") || "").slice(0, 300)).run();
    return json({ ok: true, eventId: t ? "s" + t : "waitlist", emailed: false });
  }
  return null;
}
